using System.Collections.Generic;
using UnityEngine;
namespace SokobanStudio {
public class FeedbackAudio:MonoBehaviour {
 static FeedbackAudio instance;AudioSource source,music;AudioClip musicClip;readonly Dictionary<string,AudioClip> clips=new Dictionary<string,AudioClip>();float lastBlocked=-1;
 public static void Ensure(Transform parent){if(instance)return;var g=new GameObject("Feedback Audio");g.transform.SetParent(parent);instance=g.AddComponent<FeedbackAudio>();instance.source=g.AddComponent<AudioSource>();instance.source.spatialBlend=0;instance.source.volume=.48f;if(Object.FindObjectsOfType<AudioListener>().Length==0)g.AddComponent<AudioListener>();foreach(var key in new[]{"move","push","blocked","goal","complete","click","undo","restart","save","valid","invalid"})instance.Make(key);instance.StartMusic(UnityEngine.SceneManagement.SceneManager.GetActiveScene().name);}
 void Make(string key){float duration=key=="complete"?.48f:key=="goal"?.20f:.08f;int count=(int)(22050*duration);var data=new float[count];float hz=key=="undo"?330:key=="restart"?220:key=="save"?780:key=="valid"?880:key=="invalid"?110:key=="move"?240:key=="push"?150:key=="blocked"?90:key=="goal"?660:key=="complete"?440:500;for(int i=0;i<count;i++){float t=i/22050f;float f=key=="complete"?hz*(1+(int)(t/.12f)*.25f):hz;data[i]=(Mathf.Sin(2*Mathf.PI*f*t)+.22f*Mathf.Sin(4*Mathf.PI*f*t))*Mathf.Sin(Mathf.PI*i/count)*.48f;}var c=AudioClip.Create(key,count,1,22050,false);c.SetData(data,0);clips[key]=c;}
 public static void Play(string key){if(!instance||!instance.clips.ContainsKey(key))return;if(key=="blocked"){if(Time.unscaledTime-instance.lastBlocked<.12f)return;instance.lastBlocked=Time.unscaledTime;}instance.source.PlayOneShot(instance.clips[key]);}
 // Original synthesized arrangements; no external assets or licensing dependencies.
 void StartMusic(string scene){const int rate=22050;bool menu=scene=="MainMenu",editor=scene=="LevelEditor";float beat=menu?.625f:editor?.75f:.8333333f;int total=(int)(beat*64*rate);var data=new float[total];int[] chords=menu?new[]{0,5,9,7}:editor?new[]{0,9,5,7}:new[]{0,5,2,7};int[] melody=menu?new[]{12,16,19,23,19,16,14,19}:editor?new[]{12,19,16,24,19,16,12,14}:new[]{12,19,14,16,12,19,16,14};
 for(int i=0;i<total;i++){float t=i/(float)rate;int step=(int)(t/beat),bar=step/4;float local=t%beat,barTime=t%(beat*4);int root=chords[(bar/4)%chords.Length];float rootHz=130.8128f*Mathf.Pow(2,root/12f);float padEnvelope=Mathf.Sin(Mathf.PI*barTime/(beat*4));float pad=(Mathf.Sin(2*Mathf.PI*rootHz*barTime)+.55f*Mathf.Sin(2*Mathf.PI*rootHz*Mathf.Pow(2,7f/12)*barTime))*.085f*padEnvelope;float noteHz=130.8128f*Mathf.Pow(2,(root+melody[step%8])/12f);float attack=Mathf.Min(1,local/.025f),decay=Mathf.Exp(-local/(beat*.4f));float bell=(Mathf.Sin(2*Mathf.PI*noteHz*local)+.12f*Mathf.Sin(2*Mathf.PI*noteHz*2*local))*attack*decay*(menu?.18f:editor?.13f:.09f);if(!menu&&step%2==1)bell*=.35f;float bass=Mathf.Sin(2*Mathf.PI*rootHz*.5f*barTime)*padEnvelope*.07f;float edge=Mathf.Min(1,Mathf.Min(local/.012f,(beat-local)/.035f));data[i]=Mathf.Clamp((pad+bass+bell)*Mathf.Max(0,edge),-.65f,.65f);}
 // Quantized loop length and envelopes keep the seam quiet.
 for(int i=0;i<256;i++){data[i]*=i/256f;data[total-1-i]*=i/256f;}
 musicClip=AudioClip.Create(menu?"Dock Arrival - Menu":editor?"Blueprints - Editor":"Quiet Logistics - Game",total,1,rate,false);musicClip.SetData(data,0);music=gameObject.AddComponent<AudioSource>();music.clip=musicClip;music.loop=true;music.spatialBlend=0;music.volume=0;music.Play();StartCoroutine(FadeMusic(menu?.42f:editor?.32f:.27f));}
 System.Collections.IEnumerator FadeMusic(float target){float elapsed=0;while(elapsed<.8f){elapsed+=Time.unscaledDeltaTime;music.volume=target*Mathf.Clamp01(elapsed/.8f);yield return null;}music.volume=target;}
 void OnDestroy(){if(musicClip)Destroy(musicClip);foreach(var c in clips.Values)Destroy(c);if(instance==this)instance=null;}
}
}
